INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300001, now(), now(), 'seed', '<h2>Two years, in writing</h2><p>Every product sold here carries a two-year warranty, one year longer than most manufacturers offer in the US. The extra year is ours, honoured at our own bench in Long Island City.</p><h3>What is covered</h3><ul><li>Manufacturing defects and component failure under normal use</li><li>Battery capacity falling below 80% within the first year</li><li>Dead pixels above the manufacturer''s own threshold</li></ul><h3>What is not</h3><ul><li>Liquid damage and physical impact</li><li>Devices opened by a third-party repairer</li><li>Consumables: ear tips, cables, screen films</li></ul><h3>How a repair goes</h3><p>Start a claim from your account, drop the device at the store or use the prepaid label. Median turnaround is six business days; if it runs past fourteen we ship a replacement.</p>', 'Warranty & repairs', 'Warranty & repairs', 'Two-year coverage on every product, an in-house repair bench, and what the warranty does not cover.', 'warranty, repairs, coverage', 'Warranty & repairs | USA Electronics Hub', 'warranty', 'en', -30001, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300002, now(), now(), 'seed', '<h2>Deux ans, par écrit</h2><p>Chaque produit vendu ici est garanti deux ans, soit un an de plus que la plupart des constructeurs aux États-Unis. Cette année supplémentaire est la nôtre, assurée dans notre atelier de Long Island City.</p><h3>Ce qui est couvert</h3><ul><li>Défauts de fabrication et pannes de composants en usage normal</li><li>Capacité de batterie tombant sous 80 % la première année</li><li>Pixels morts au-delà du seuil du constructeur</li></ul><h3>Ce qui ne l''est pas</h3><ul><li>Dégâts des liquides et chocs</li><li>Appareils ouverts par un réparateur tiers</li><li>Consommables : embouts, câbles, films d''écran</li></ul><h3>Le déroulé d''une réparation</h3><p>Ouvrez un dossier depuis votre compte, déposez l''appareil en boutique ou utilisez l''étiquette prépayée. Le délai médian est de six jours ouvrés ; au-delà de quatorze, nous expédions un remplacement.</p>', 'Garantie et réparations', 'Garantie et réparations', 'Deux ans de garantie sur chaque produit, un atelier interne, et ce que la garantie ne couvre pas.', 'garantie, réparation, couverture', 'Garantie et réparations | USA Electronics Hub', 'garantie', 'fr', -30001, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

-- page: buying-guides (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-30002, now(), now(), 'seed', 'buying-guides', 'PAGE', 11, true, '65f023632bc46470c104b75f', 'PUBLISHED', null, null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, null)
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300003, now(), now(), 'seed', '<h2>Nothing ships untested</h2><p>We carry about four hundred products, out of roughly three thousand we are offered each year. The difference is a week on the bench.</p><h3>What we measure</h3><ul><li><strong>Laptops:</strong> sustained load temperature over 30 minutes, fan noise at 50 cm, panel colour coverage</li><li><strong>Headphones:</strong> frequency response against a compensated target, active-cancellation depth at 100 Hz</li><li><strong>Televisions:</strong> peak and sustained brightness, input latency in game mode</li><li><strong>Phones:</strong> screen brightness under 10,000 lux, charge cycle to 80%</li></ul><h3>What gets turned away</h3><p>Anything that throttles below its advertised sustained performance, anything whose battery is glued past the point of repair, and anything whose manufacturer will not commit to four years of security updates.</p>', 'How we choose what we sell', 'How we choose what we sell', 'The bench tests every product passes before it reaches the catalogue, and the ones we turn away.', 'testing, curation, buying guide', 'How we choose what we sell | USA Electronics Hub', 'how-we-choose', 'en', -30002, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300004, now(), now(), 'seed', '<h2>Rien n''entre sans passer au banc</h2><p>Nous référençons environ quatre cents produits sur les trois mille qu''on nous propose chaque année. L''écart, c''est une semaine de banc d''essai.</p><h3>Ce que nous mesurons</h3><ul><li><strong>Ordinateurs portables :</strong> température en charge continue sur 30 minutes, bruit de ventilation à 50 cm, couverture colorimétrique de la dalle</li><li><strong>Casques :</strong> réponse en fréquence face à une cible compensée, profondeur de réduction active à 100 Hz</li><li><strong>Téléviseurs :</strong> luminance de crête et soutenue, latence d''affichage en mode jeu</li><li><strong>Téléphones :</strong> luminosité sous 10 000 lux, cycle de charge jusqu''à 80 %</li></ul><h3>Ce que nous refusons</h3><p>Tout ce qui bride en dessous de la performance annoncée, tout ce dont la batterie est collée au point d''être irréparable, et tout constructeur refusant de s''engager sur quatre ans de mises à jour de sécurité.</p>', 'Comment nous choisissons ce que nous vendons', 'Comment nous choisissons ce que nous vendons', 'Les tests que chaque produit traverse avant d''entrer au catalogue, et ceux que nous refusons.', 'tests, sélection, guide d''achat', 'Comment nous choisissons | USA Electronics Hub', 'comment-nous-choisissons', 'fr', -30002, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

-- page: trade-in-program (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-30003, now(), now(), 'seed', 'trade-in-program', 'PAGE', 12, true, '65f023632bc46470c104b75f', 'PUBLISHED', null, null, 1, 'seed', 'seed', null, false, null, null, true, null, null, null, null, null)
