INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300005, now(), now(), 'seed', '<h2>Send it in, get credit</h2><ol><li>Get a quote online — model, storage, condition</li><li>We mail a padded box with a prepaid label</li><li>Credit lands within three business days of the device arriving</li></ol><h2>What happens to it</h2><p>Roughly six devices in ten are refurbished and resold with our own one-year warranty. The rest go to a certified R2v3 recycler in New Jersey; nothing is shipped overseas for disposal.</p><h2>Before you send</h2><ul><li>Sign out of the manufacturer''s account — a locked device is worth nothing to anyone</li><li>Back up, then erase</li><li>Leave the charger; we do not need it and it lowers nothing</li></ul>', 'Trade-in programme', 'Trade-in programme', 'Send in an old device, get store credit within three business days, and see where it ends up.', 'trade-in, recycling, credit', 'Trade-in programme | USA Electronics Hub', 'trade-in', 'en', -30003, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300006, now(), now(), 'seed', '<h2>Envoyez, recevez un avoir</h2><ol><li>Obtenez une estimation en ligne — modèle, stockage, état</li><li>Nous envoyons un carton matelassé avec étiquette prépayée</li><li>L''avoir est crédité sous trois jours ouvrés après réception</li></ol><h2>Ce que devient l''appareil</h2><p>Six appareils sur dix environ sont reconditionnés et revendus avec notre garantie d''un an. Les autres partent chez un recycleur certifié R2v3 dans le New Jersey ; rien n''est expédié à l''étranger pour destruction.</p><h2>Avant l''envoi</h2><ul><li>Déconnectez le compte constructeur — un appareil verrouillé ne vaut rien</li><li>Sauvegardez, puis effacez</li><li>Gardez le chargeur : il ne change rien à l''estimation</li></ul>', 'Programme de reprise', 'Programme de reprise', 'Envoyez un ancien appareil, recevez un avoir sous trois jours ouvrés, et sachez ce qu''il devient.', 'reprise, recyclage, avoir', 'Programme de reprise | USA Electronics Hub', 'reprise', 'fr', -30003, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

