INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300007, now(), now(), 'seed', '<h2>456 Tech Avenue, New York</h2><p>This page sits under “Location”, which also makes it the breadcrumb check: it should read Home › Location › Store hours & directions.</p><ul><li><strong>Monday–Friday</strong> 10am–8pm</li><li><strong>Saturday</strong> 10am–7pm</li><li><strong>Sunday</strong> 12pm–6pm</li></ul><h3>Getting here</h3><p>Two minutes from the 28th Street station on the 1 and the R. Metered parking on the avenue; the garage on 27th validates for two hours with any purchase.</p><h3>Repair desk</h3><p>At the back of the store, no appointment before 11am, appointments only after.</p>', 'Store hours & directions', 'Store hours & directions', 'Opening hours, subway directions and the repair-bench desk at 456 Tech Avenue.', 'hours, directions, store', 'Store hours & directions | USA Electronics Hub', 'store-hours', 'en', -30004, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300008, now(), now(), 'seed', '<h2>456 Tech Avenue, New York</h2><p>Cette page est rattachée à « Notre emplacement », ce qui en fait le contrôle du fil d''Ariane : Accueil › Notre emplacement › Horaires et accès.</p><ul><li><strong>Lundi–vendredi</strong> 10h–20h</li><li><strong>Samedi</strong> 10h–19h</li><li><strong>Dimanche</strong> 12h–18h</li></ul><h3>Y venir</h3><p>À deux minutes de la station 28th Street, lignes 1 et R. Stationnement payant sur l''avenue ; le parking de la 27e offre deux heures pour tout achat.</p><h3>Comptoir de réparation</h3><p>Au fond de la boutique : sans rendez-vous avant 11h, sur rendez-vous ensuite.</p>', 'Horaires et accès', 'Horaires et accès', 'Horaires d''ouverture, accès en métro et comptoir de réparation au 456 Tech Avenue.', 'horaires, accès, boutique', 'Horaires et accès | USA Electronics Hub', 'horaires-et-acces', 'fr', -30004, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

