INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300009, now(), now(), 'seed', '<h2>No expiry, no fees</h2><p>Cards run from $25 to $1,000, digital and delivered in minutes, or printed on a matte card and posted free.</p><p>They never expire, carry no maintenance fee, and any remaining balance stays on the card — which is not true of most retail cards, and is the reason this page exists.</p><p>The page also carries a canonical URL and an Open Graph image, which makes it the check on the storefront''s SEO rendering.</p>', 'Gift cards', 'Gift cards', 'Digital and physical gift cards from $25 to $1,000, with no expiry and no fees.', 'gift card, voucher', 'Gift cards | USA Electronics Hub', 'gift-cards', 'en', -30005, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300010, now(), now(), 'seed', '<h2>Sans expiration, sans frais</h2><p>Les cartes vont de 25 à 1 000 $, en version numérique livrée en quelques minutes ou imprimée sur carte mate et postée gratuitement.</p><p>Elles n''expirent jamais, ne portent aucun frais de gestion, et le solde restant est conservé — ce qui n''est pas le cas de la plupart des cartes du commerce, et justifie cette page.</p><p>Elle porte aussi une URL canonique et une image Open Graph, ce qui en fait le contrôle du rendu SEO.</p>', 'Cartes cadeaux', 'Cartes cadeaux', 'Cartes cadeaux numériques et physiques de 25 à 1 000 $, sans expiration ni frais.', 'carte cadeau, bon d''achat', 'Cartes cadeaux | USA Electronics Hub', 'cartes-cadeaux', 'fr', -30005, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

