INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300011, now(), now(), 'seed', '<h2>Where we stand</h2><p>This page is flagged <code>noindex</code>: it should render in the storefront but stay out of the sitemap. That is the check on the SEO flag.</p><ul><li>Target: WCAG 2.2 level AA across the storefront</li><li>Known gap: the comparison table is not yet reachable by keyboard alone</li><li>Report a barrier: <a href="mailto:access@usaelectronics.com">access@usaelectronics.com</a></li></ul>', 'Accessibility statement', 'Accessibility statement', 'Our WCAG conformance status — a page deliberately kept out of the index.', 'accessibility, wcag', 'Accessibility statement | USA Electronics Hub', 'accessibility', 'en', -30006, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300012, now(), now(), 'seed', '<h2>Où nous en sommes</h2><p>Cette page est marquée <code>noindex</code> : elle doit s''afficher dans la boutique mais disparaître du sitemap. C''est le contrôle du drapeau.</p><ul><li>Objectif : WCAG 2.2 niveau AA sur l''ensemble de la boutique</li><li>Écart connu : le tableau comparatif n''est pas encore atteignable au clavier seul</li><li>Signaler un obstacle : <a href="mailto:access@usaelectronics.com">access@usaelectronics.com</a></li></ul>', 'Déclaration d''accessibilité', 'Déclaration d''accessibilité', 'Notre niveau de conformité WCAG — page volontairement exclue de l''indexation.', 'accessibilité, wcag', 'Déclaration d''accessibilité | USA Electronics Hub', 'accessibilite', 'fr', -30006, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

